export const markEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from("event_interested")
      .insert({ event_id: eventId, user_id: userId });
      
    if (error) throw error;
    
    // Update user's upcoming events count - using normal function call instead of rpc
    try {
      const { data: profile, error: profileError } = await supabase
        .from("profiles")
        .select("events_upcoming")
        .eq("id", userId)
        .single();
      
      if (!profileError && profile) {
        await supabase
          .from("profiles")
          .update({ events_upcoming: (profile.events_upcoming || 0) + 1 })
          .eq("id", userId);
      }
    } catch (error) {
      console.error("Error updating user's upcoming events count:", error);
    }
    
    return true;
  } catch (error) {
    console.error("Error marking event interest:", error);
    return false;
  }
};

export const removeEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from("event_interested")
      .delete()
      .eq("event_id", eventId)
      .eq("user_id", userId);
      
    if (error) throw error;
    
    // Update user's upcoming events count - using normal function call instead of rpc
    try {
      const { data: profile, error: profileError } = await supabase
        .from("profiles")
        .select("events_upcoming")
        .eq("id", userId)
        .single();
      
      if (!profileError && profile && profile.events_upcoming && profile.events_upcoming > 0) {
        await supabase
          .from("profiles")
          .update({ events_upcoming: profile.events_upcoming - 1 })
          .eq("id", userId);
      }
    } catch (error) {
      console.error("Error updating user's upcoming events count:", error);
    }
    
    return true;
  } catch (error) {
    console.error("Error removing event interest:", error);
    return false;
  }
};

// Event attendees functions
export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // Check if already checked in
    const { data: existingCheckIn, error: checkError } = await supabase
      .from("event_attendees_new")
      .select("*")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    // If not already checked in, create a check-in record
    if (!existingCheckIn) {
      const { error } = await supabase
        .from("event_attendees_new")
        .insert({ event_id: eventId, user_id: userId });
        
      if (error) throw error;
      
      // Update user's attended events count - using normal function call instead of rpc
      try {
        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("events_attended")
          .eq("id", userId)
          .single();
        
        if (!profileError && profile) {
          await supabase
            .from("profiles")
            .update({ events_attended: (profile.events_attended || 0) + 1 })
            .eq("id", userId);
        }
      } catch (error) {
        console.error("Error updating user's attended events count:", error);
      }
    }
    
    return true;
  } catch (error) {
    console.error("Error checking in user to event:", error);
    return false;
  }
};

