// User event history functions
export const getUserAttendedEvents = async (userId: string): Promise<any[]> => {
  try {
    const { data, error } = await supabase
      .from("event_attendees_new")
      .select("*, event:event_id(*)")
      .eq("user_id", userId)
      .order("check_in_time", { ascending: false });
      
    if (error) throw error;
    
    // Flatten the result for easier consumption
    return (data || []).map(item => ({
      id: item.event?.id,
      title: item.event?.title,
      description: item.event?.description,
      image_url: item.event?.image_url,
      location: item.event?.location,
      event_date: item.event?.event_date,
      check_in_time: item.check_in_time
    }));
  } catch (error) {
    console.error("Error getting user attended events:", error);
    return [];
  }
};

