export const promoteStudentToInfoOfficer = async (userId: string): Promise<boolean> => {
  try {
    // Check if the user already has the role
    const { data: existingRole, error: checkError } = await supabase
      .from("user_roles")
      .select("*")
      .eq("user_id", userId)
      .eq("role", "information_officer")
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    // If the user doesn't have the role yet, assign it
    if (!existingRole) {
      const { error } = await supabase
        .from("user_roles")
        .insert({ user_id: userId, role: "information_officer" });
        
      if (error) throw error;
    }
    
    return true;
  } catch (error) {
    console.error("Error promoting student to information officer:", error);
    return false;
  }
};

// Notification functions
export const createEventReminderNotifications = async (eventId: string, reminderText: string): Promise<boolean> => {
  try {
    // Get users who are interested in this event
    const { data: interestedUsers, error: userError } = await supabase
      .from("event_interested")
      .select("user_id")
      .eq("event_id", eventId);
      
    if (userError) throw userError;
    
    if (!interestedUsers || interestedUsers.length === 0) {
      return true; // No users to notify
    }
    
    // Get event details
    const { data: eventData, error: eventError } = await supabase
      .from("events")
      .select("title")
      .eq("id", eventId)
      .single();
      
    if (eventError) throw eventError;
    
    // Create notifications for each interested user
    const notifications = interestedUsers.map(user => ({
      user_id: user.user_id,
      title: "Event Reminder",
      message: reminderText || `Reminder: The event "${eventData.title}" is coming up soon!`,
      type: "event_reminder",
      related_id: eventId
    }));
    
    const { error: notifError } = await supabase
      .from("notifications")
      .insert(notifications);
      
    if (notifError) throw notifError;
    
    return true;
  } catch (error) {
    console.error("Error creating event reminder notifications:", error);
    return false;
  }
};
